function nextClassDate(classItem,now=new Date()){let today=new Date(now.getFullYear(),now.getMonth(),now.getDate());for(let offset=0;offset<7;offset++){let candidate=new Date(today);candidate.setDate(today.getDate()+offset);if(classDays(classItem).includes(candidate.getDay()))return `${candidate.getFullYear()}-${String(candidate.getMonth()+1).padStart(2,'0')}-${String(candidate.getDate()).padStart(2,'0')}`}return ''}
