const newsPostText=(post,key)=>post.sample?t(post[key+'Zh'],post[key]):post[key];
function newsImage(item){return newsPostImage(item.post.image)||'/assets/beamal-art.jpg'}
function newsDetails(item){let image=newsImage(item);return `<article class="upcoming-detail teacher-news-detail"><div class="upcoming-detail-copy"><p class="upcoming-label">${t('發布日期','Release date')}</p><time datetime="${item.releaseDate}">${upcomingDate(item.releaseDate)}</time><h3>${esc(item.title)}</h3><p class="upcoming-detail-description">${esc(item.description)}</p><div class="news-detail-content">${esc(newsPostText(item.post,'content'))}</div></div><img class="news-detail-image" src="${image}" alt="${esc(item.title)}"></article>`}
function upcomingEvents(limit=Infinity){let items=newsItems(),visible=items.slice(0,limit);if(!visible.length)return `<p class="empty">${t('目前沒有消息','No news at the moment.')}</p>`;selectedUpcomingEvent=Math.min(selectedUpcomingEvent,visible.length-1);let selected=visible[selectedUpcomingEvent];return `<div class="upcoming-layout"><div class="upcoming-options" role="radiogroup" aria-label="${t('最新消息','Latest news')}">${visible.map((item,index)=>`<label class="upcoming-option ${index===selectedUpcomingEvent?'selected':''}"><input type="radio" name="upcoming-event" value="${index}" ${index===selectedUpcomingEvent?'checked':''}><span>${esc(item.title)}</span><time datetime="${item.releaseDate}">${upcomingDate(item.releaseDate)}</time><small>${esc(item.description)}</small></label>`).join('')}</div>${newsDetails(selected)}</div>`}
function newsPage(){let items=newsItems();return `<section class="news-page"><div class="news-page-heading"><p class="news-eyebrow">BEAMAL ART STUDIO</p><h1 class="title">${t('最新消息','News')}</h1><p>${t('畫室活動、作品與藝術消息','Studio events, artworks and art news')}</p></div><div class="news-entries">${items.map(item=>`<details class="news-entry"><summary><img class="news-entry-image" src="${newsImage(item)}" alt=""><span class="news-entry-copy"><span class="news-entry-meta"><span class="news-kind">${item.post.sample?t(item.post.categoryZh,item.post.categoryEn):t('畫室消息','Studio news')}</span><time datetime="${item.releaseDate}">${upcomingDate(item.releaseDate)}</time></span><span class="news-entry-title">${esc(item.title)}</span><span class="news-entry-summary">${esc(item.description)}</span><span class="news-entry-more">${t('閱讀更多','Read more')} <span aria-hidden="true">↗</span></span></span></summary>${newsDetails(item)}</details>`).join('')||`<p class="empty">${t('目前沒有消息','No news at the moment.')}</p>`}</div></section>`}
function home(){return `<section class="home-hero"><div class="home-copy"><h1>${t('透過藝術表達自己，訴說你的故事','Express yourself and tell your story through art')}</h1><ul class="home-services"><li>${t('兒童常規藝術課程','Regular Art Classes for Kids')}</li><li>${t('繪本課程','Storybook Class')}</li><li>${t('縫紉課程','Sewing Class')}</li></ul><a class="button" href="/classes" data-go="/classes">${t('探索課程','Explore classes')}</a></div><div class="home-photo">${art(7)}</div></section><section class="section"><h2>${t('曾舉辦的活動','Past Events')}</h2><div class="event-grid"><article class="event-card">${art(3)}<h3>${t('黏土班','Clay Classes')}</h3></article><article class="event-card">${art(5)}<h3>${t('素描班','Sketching Classes')}</h3></article><article class="event-card">${art(4)}<h3>${t('繪畫班','Drawing Classes')}</h3></article></div></section><section class="section"><h2>${t('最新消息','Latest News')}</h2><p class="sub">${t('畫室動態','Studio updates')}</p>${upcomingEvents(4)}<a class="button ghost news-more" href="/news" data-go="/news">${t('更多消息','More news')}</a></section>`}

function about(){return `<h1 class="title">${t('關於我們','About Us')}</h1><div class="about-copy-grid"><section><h2>Mission &amp; Vision</h2><p>sample</p></section><section><h2>Our Story</h2><p>sample</p></section></div><section class="section"><h2>${t('更多活動照片','More Studio Photos')}</h2><div class="event-grid">${[8,9].map(i=>`<div class="event-card">${art(i)}</div>`).join('')}</div></section>`}

const portfolioPosition=index=>{let offset=(index-portfolioActive+portfolioSlides.length)%portfolioSlides.length;return offset===0?'active':offset===1?'next':offset===portfolioSlides.length-1?'previous':offset<portfolioSlides.length/2?'far-next':'far-previous'};
const portfolioStatusText=()=>t(`第 ${portfolioActive+1} 張作品，共 ${portfolioSlides.length} 張`,`Artwork ${portfolioActive+1} of ${portfolioSlides.length}`);
function portfolio(){return `<section class="portfolio-intro"><div class="portfolio-intro-copy"><span class="portfolio-eyebrow">BEAMAL ART STUDIO</span><h1>${t('作品集','Portfolio')}</h1><div class="portfolio-flourish" aria-hidden="true"><span></span><span></span><span></span></div><p>${t('學生作品','Student artworks')}</p></div><div class="portfolio-feature"><div class="portfolio-slider" aria-label="${t('作品輪播','Artwork slideshow')}"><div class="portfolio-stage">${portfolioSlides.map((i,index)=>`<div class="portfolio-slide" data-position="${portfolioPosition(index)}" ${index===portfolioActive?'':'inert'}>${art(i)}</div>`).join('')}</div><div class="portfolio-controls"><button class="portfolio-arrow" data-action="portfolio-prev" aria-label="${t('上一張作品','Previous artwork')}">‹</button><div class="portfolio-status" role="status" aria-live="polite"><span class="portfolio-status-sr">${portfolioStatusText()}</span><div class="portfolio-progress" aria-hidden="true">${portfolioSlides.map((_,index)=>`<span class="${index===portfolioActive?'active':''}"></span>`).join('')}</div></div><button class="portfolio-arrow" data-action="portfolio-next" aria-label="${t('下一張作品','Next artwork')}">›</button></div></div></div></section><div class="portfolio-gallery-heading"><h2>${t('作品','Works')}</h2><span>${String(photos.length-10).padStart(2,'0')} ${t('件作品','works')}</span></div><div class="portfolio-gallery">${photos.slice(10).map((_,i)=>i+10).filter(i=>!portfolioSlides.includes(i)).map(i=>`<div class="portfolio-piece">${art(i)}</div>`).join('')}</div>`}
function syncPortfolioRotation(p){if(portfolioTimer!==null&&typeof window.clearTimeout==='function')window.clearTimeout(portfolioTimer);portfolioTimer=null;if(p!=='/portfolio'||typeof window.setTimeout!=='function')return;portfolioTimer=window.setTimeout(()=>{if(document.hidden){syncPortfolioRotation('/portfolio');return}rotatePortfolio(1)},5000)}
function rotatePortfolio(direction){if(path()!=='/portfolio')return;portfolioActive=(portfolioActive+direction+portfolioSlides.length)%portfolioSlides.length;let slider=document.querySelector('.portfolio-slider');if(slider){slider.querySelectorAll('.portfolio-slide').forEach((slide,index)=>{slide.dataset.position=portfolioPosition(index);slide.inert=index!==portfolioActive});slider.querySelector('.portfolio-status-sr').textContent=portfolioStatusText();slider.querySelectorAll('.portfolio-progress span').forEach((segment,index)=>segment.classList.toggle('active',index===portfolioActive))}syncPortfolioRotation('/portfolio')}
function courseSchedule(courseId){let classes=sortedClasses(db.classes.filter(item=>item.course===courseId));return classes.length?`<section class="course-schedule"><h2>${t('班別時段','Class times')}</h2><ul>${classes.map(item=>`<li><strong>${slotText(item)}</strong><span>${lessonsLabel(termLessons(item))}</span></li>`).join('')}</ul></section>`:`<p class="empty">${t('暫無班別時間','No class times available.')}</p>`}
function detail(id){let c=courses.find(c=>c.id===id);if(!c){let list=sortedClasses(db.classes.filter(item=>item.course===decodeURIComponent(id)));if(!list.length)return missing();let first=list[0];return `<div class="about"><div>${classArtwork(first.course,0,first)}</div><div><h1 class="title">${classTitle(first)}</h1><p class="sub">${t('課程班別','Course classes')}</p>${courseSchedule(first.course)}<button class="ghost" data-go="/classes">${t('返回課程','Back to courses')}</button></div></div>`}return `<div class="about"><div>${classArtwork(id,courses.indexOf(c))}</div><div><h1 class="title">${name(id)}</h1><p class="sub">Sample</p><p>${t('年齡','Age')}: Sample · ${money(c.price)}</p>${courseSchedule(id)}<button data-enrol="${id}">Join Class</button></div></div>`}
function privacy(){return `<h1 class="title">${t('私隱政策','Privacy Policy')}</h1><div class="panel"><p>Sample</p></div>`}

function login(){return `<div class="form"><h1 class="title login-title">${t('歡迎回來','Welcome back')}</h1><p class="sub login-title">Beamal Art Studio</p><form id="login"><label for="username">Username / Phone number / Email</label><input id="username" name="username" value="" autocomplete="off" required><label for="password">Password</label><input id="password" name="password" type="password" autocomplete="off"><p id="login-error" role="alert" class="error"></p><button>${t('登入','Login')}</button></form></div>`}
function joinForm(account=false){let c=courses.find(c=>c.id===join.course);return `<h1 class="title">${t('開始你的創作旅程','Begin your creative journey')}</h1><div class="form"><div class="progress">${[t('1 選擇課程','1 Select course'),t('2 學生資料','2 Details'),t('3 確認','3 Review')].map((s,i)=>`<span class="${join.step===i+1?'active':''}">${s}</span>`).join('')}</div><form id="join">${join.step===1?`<label for="course">${t('選擇課程','Select course')}</label><select id="course" name="course">${courses.map(c=>`<option value="${c.id}" ${join.course===c.id?'selected':''}>${name(c.id)}</option>`).join('')}</select><fieldset class="time-list"><legend>${t('選擇時段','Choose a time')}</legend>${sortedJoinClasses(db.classes.filter(c=>c.course===join.course)).map(c=>`<label class="time-option ${!bookable(c)?'unavailable':''}"><input type="radio" name="classId" value="${c.id}" ${!bookable(c)?'disabled':''} ${join.classId===c.id&&bookable(c)?'checked':''} required><span><strong>${slotText(c)}</strong><small class="class-date-period">${joinClassDateLabel(c)}</small><small>${lessonsLabel(termLessons(c))}</small><small>${free(c)<=0?t('滿額','Full'):bookable(c)?t('有位','Available'):t('暫不可報名','Not currently available')}</small></span></label>`).join('')}</fieldset><p>${t('費用','Fee')}: ${money(c.price)} · ${lessonsLabel(termLessons(cl(join.classId)))}</p>`:join.step===2?`<label for="student">${t('學生姓名','Student name')}</label><input id="student" name="student" value="${esc(join.student??'')}" required><label for="phone">${t('電話','Phone')}</label><input id="phone" name="phone" inputmode="numeric" pattern="[0-9]+" value="${esc(join.phone??'')}" required><label for="email">${t('電郵','Email')}</label><input id="email" name="email" type="text" value="${esc(join.email??'')}" required><p id="join-error" role="alert" class="error"></p>`:`<h2>${name(join.course)}</h2><p>${slotText(cl(join.classId))}</p><p class="class-date-period">${joinClassDateLabel(cl(join.classId))}</p><p>${esc(join.student)} · ${esc(join.email)}</p><p>${t('費用','Fee')}: ${money(c.price)} · ${lessonsLabel(termLessons(cl(join.classId)))}</p><p class="notice">${free(cl(join.classId))>0?t('提交後可前往付款。','Proceed to payment after submitting.'):t('班別已滿，提交後加入候補。','Class is full; submit to join the waitlist.')}</p><p class="notice">${t('付款成功後，你會收到電郵以啟用學生帳戶。','Once payment is successful, you will receive an email to activate your student account.')}</p>`}<div class="actions join-actions">${join.step>1?`<button type="button" class="ghost" data-action="joinback">${t('上一步','Back')}</button>`:''}<button>${join.step===3?t('提交報名','Submit enrolment'):t('下一步','Continue')}</button></div></form></div>`}
const latestEnrolment=()=>db.bookings.find(b=>b.id===sessionStorage.getItem('beamal-enrolment'));
function confirmation(){let b=latestEnrolment();if(!b)return missing();return `<div class="form"><h1 class="title">${t('已收到報名！','Enrolment received!')}</h1><p class="payment-status">Status: ${b.paid?t('已付款','Paid'):t('待付款','Awaiting payment')}</p><p>${t('付款成功後，你會收到電郵以啟用學生帳戶。','Once payment is successful, you will receive an email to activate your student account.')}</p><button data-go="${b.paid?'/payment-success':'/payment'}">${b.paid?t('查看付款結果','View payment result'):t('前往付款','Click to Pay')}</button></div>`}
function paymentPage(){return `<div class="external-payment-message"><p>Payment will be processed through an external payment service.</p><button data-action="complete-payment">${t('模擬付款成功','Simulate successful payment')}</button></div>`}
function paymentSuccess(){let b=latestEnrolment();if(!b?.paid)return missing();return `<div class="form payment-success"><div class="success-mark" aria-hidden="true">✓</div><h1 class="title">${t('付款成功','Payment successful')}</h1><p>${t('請查看電郵，啟用你的學生帳戶。','Check your email to activate your student account.')}</p><p class="sub">${t('啟用帳戶後即可登入，查看課程及付款紀錄。','Once your account is activated, log in to view your classes and payment records.')}</p><button data-go="/login">${t('登入','Login')}</button></div>`}

function bookings(list,teacher=false){if(!list.length)return `<p class="empty">${t('暫未有課程紀錄','No class records yet')}</p>`;return `<div class="table-wrap"><table><thead><tr><th>${t('學生／編號','Student / ID')}</th><th>${t('課程／時間','Class / Time')}</th><th>${t('狀態','Status')}</th>${teacher?`<th>${t('提交日期','Submit date')}</th><th>${t('操作','Action')}</th>`:''}</tr></thead><tbody>${(teacher?sortedRecords(list):[...list].sort((a,b)=>weeklyRank(cl(b.classId))-weeklyRank(cl(a.classId)))).map(b=>{let c=cl(b.classId);return `<tr><td>${esc(b.student)}<br><small>${b.id}</small></td><td>${classTitle(c)}<br>${slotText(c)}${!teacher?studentScheduleInfo(b):''}${!teacher?`<div class="booking-dates"><strong>${t('上課日期','Class dates')}</strong>${b.paid&&b.status==='confirmed'?`<ol>${bookingLessonDates(b).map(date=>`<li><time datetime="${date}">${upcomingDate(date)}</time></li>`).join('')}</ol>`:`<span>${t('付款後顯示','Shown after payment')}</span>`}</div>`:''}</td><td>${teacher?status(b.status):b.paid&&b.status==='confirmed'?t('已加入','Joining'):t('待付款','Awaiting payment')}</td>${teacher?`<td>${esc(dateTime(b.submittedAt))}</td><td><button class="ghost" data-view-student="${b.id}">${t('學生詳情','Student details')}</button>${b.status==='waitlist'?`<button data-confirm="${b.id}">${t('確認候補','Confirm waitlist')}</button>`:!b.paid?`<button data-pay="${b.id}">${t('確認付款','Confirm payment')}</button>`:''}</td>`:''}</tr>`}).join('')}</tbody></table></div>`}

function requests(teacher){let list=db.requests.filter(r=>teacher||r.student===db.student.name);return list.length?list.map(r=>`<div class="panel"><div class="row"><span>${esc(r.student)} · ${name(cl(r.to).course)}<br>${cl(r.from).date} ${cl(r.from).time} → ${cl(r.to).date} ${cl(r.to).time}</span><span>${status(r.status)}</span></div>${teacher&&r.status==='pending'?`<button data-approve="${r.id}">${t('批准','Approve')}</button> <button class="ghost" data-reject="${r.id}">${t('拒絕','Decline')}</button>`:''}</div>`).join(''):`<p class="empty">${t('暫無轉堂申請','No change requests')}</p>`}
function sortedPayments(list){return [...list].sort((a,b)=>timeRank(b.paidAt||b.submittedAt)-timeRank(a.paidAt||a.submittedAt)||b.id.localeCompare(a.id,undefined,{numeric:true}))}
function payments(list,teacher){if(!list.length)return `<p class="empty">${t('暫未有付款紀錄','No payment records yet')}</p>`;return `<div class="table-wrap"><table><thead><tr><th>Record</th><th>${t('金額','Amount')}</th><th>${t('付款日期','Payment date')}</th>${teacher?`<th>${t('提交日期','Submit date')}</th>`:''}<th>Status</th></tr></thead><tbody>${sortedPayments(list).map(b=>`<tr><td>${esc(b.student)} · ${esc(b.id)}</td><td>${money(b.amount)}</td><td>${b.paidAt?esc(dateTime(b.paidAt)):'—'}</td>${teacher?`<td>${esc(dateTime(b.submittedAt))}</td>`:''}<td>${b.paid?t('已付款','Paid'):t('待付款','Unpaid')}${teacher&&!b.paid&&b.status!=='waitlist'?` <button data-pay="${b.id}">${t('確認付款','Confirm payment')}</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
const monthKey=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`;
function incomeMonths(){return Array.from({length:6},(_,i)=>{let d=new Date(incomeEnd.getFullYear(),incomeEnd.getMonth()-5+i,1),month=monthKey(d);return {month,total:db.bookings.filter(b=>b.paid&&recordMonth(b.paidAt)===month).reduce((sum,b)=>sum+b.amount,0)}})}
function incomePage(){let months=incomeMonths(),max=Math.max(1,...months.map(m=>m.total)),current=incomeMonth||monthKey(incomeEnd),total=db.bookings.filter(b=>b.paid&&recordMonth(b.paidAt)===current).reduce((sum,b)=>sum+b.amount,0),records=incomeMonth?db.bookings.filter(b=>recordMonth(b.paidAt||b.submittedAt)===incomeMonth):db.bookings;return `<div class="row income-heading"><h1 class="title">${t('收款與收入','Payments & income')}</h1><button data-action="export-excel">Output to Excel</button></div><section class="panel income-chart"><div class="row"><div><h2>${t('收款','Collections')}</h2><p>${current}</p><strong class="income-total">${money(total)}</strong></div><div class="income-controls"><button class="ghost" data-action="income-prev" aria-label="${t('前六個月','Previous six months')}">‹</button><label>${t('月份','Month')}<input id="income-month" type="month" value="${current}"></label><button class="ghost" data-action="income-next" aria-label="${t('後六個月','Next six months')}">›</button></div></div><div class="income-bars" role="group" aria-label="${t('每月收款','Monthly collections')}">${months.map(m=>`<button class="income-bar ${m.month===current?'selected':''}" data-income-month="${m.month}" aria-pressed="${m.month===current}" aria-label="${m.month}: ${money(m.total)}"><span class="bar-value">${money(m.total)}</span><span class="bar-track"><span class="bar-fill" style="height:${m.total/max*100}%"></span></span><span class="bar-month">${m.month}</span></button>`).join('')}</div></section><section class="panel"><div class="row"><h2>Record${incomeMonth?' · '+incomeMonth:''}</h2>${incomeMonth?`<button class="ghost" data-action="income-all">${t('所有記錄','All records')}</button>`:''}</div>${payments(records,true)}</section>`}
function incomeExportSheets(){let records=sortedPayments(db.bookings),totals=new Map();for(let b of records){if(b.paid&&b.paidAt){let m=recordMonth(b.paidAt);totals.set(m,(totals.get(m)||0)+b.amount)}}return [{sheet:'Payment records',data:[['Record','Student','Course','Class ID','Amount (HKD)','Payment date','Status','Submit date'],...records.map(b=>[b.id,b.student,name(cl(b.classId).course),classNumber(cl(b.classId)),b.amount,b.paidAt||'',b.paid?'Paid':'Unpaid',dateTime(b.submittedAt)])],columns:[16,22,18,16,20,25,16,25].map(width=>({width})),stickyRowsCount:1},{sheet:'Monthly collections',data:[['Month','Collections (HKD)'],...[...totals].sort((a,b)=>b[0].localeCompare(a[0]))],columns:[{width:20},{width:24}],stickyRowsCount:1}]}
async function exportIncome(){if(role!=='teacher')return;try{let blob=await writeExcelFile(incomeExportSheets()).toBlob(),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Beamal-payments.xlsx';a.style.display='none';document.body.append(a);a.click();setTimeout(()=>{URL.revokeObjectURL(url);a.remove()},1000)}catch{toast(t('匯出失敗，請再試一次。','Export failed. Please try again.'))}}
function newEnrolments(){return db.bookings.filter(b=>b.status==='pending'||b.status==='waitlist')}
function stats(){return `<div class="stats teacher-stats"><button class="stat" data-tab="student-list">${t('學生人數','Students')}<strong>${studentList().length}</strong><span>${t('查看學生名單 →','View students →')}</span></button><button class="stat" data-tab="new-enrolments">${t('新報名','New enrolments')}<strong>${newEnrolments().length}</strong><span>${t('查看新報名 →','View new enrolments →')}</span></button></div>`}

function studentCalendar(){let year=calendarMonth.getFullYear(),month=calendarMonth.getMonth(),first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),offset=(first.getDay()+6)%7,today=new Date(),cells=Math.ceil((offset+days)/7)*7;let confirmed=mine().filter(b=>b.paid&&b.status==='confirmed');return `<section class="calendar-card" aria-label="My Calendar"><div class="calendar-heading"><h1>My Calendar</h1><div class="calendar-controls"><button class="ghost" data-action="calendar-today">${t('今天','Today')}</button><button class="ghost" data-action="calendar-prev" aria-label="${t('上一個月','Previous month')}">‹</button><h2>${t(`${year} 年 ${month+1} 月`,new Intl.DateTimeFormat('en',{month:'long',year:'numeric'}).format(first))}</h2><button class="ghost" data-action="calendar-next" aria-label="${t('下一個月','Next month')}">›</button></div></div><div class="calendar-grid">${['一','二','三','四','五','六','日'].map((d,i)=>`<div class="calendar-weekday">${t('星期'+d,['Mon','Tue','Wed','Thu','Fri','Sat','Sun'][i])}</div>`).join('')}${Array.from({length:cells},(_,i)=>{let day=i-offset+1;if(day<1||day>days)return '<div class="calendar-day outside" aria-hidden="true"></div>';let date=new Date(year,month,day),key=`${year}-${String(month+1).padStart(2,'0')}-${String(day).padStart(2,'0')}`,events=confirmed.filter(b=>{let c=cl(b.classId);return bookingLessonDates(b).includes(key)}).sort((a,b)=>cl(b.classId).time.localeCompare(cl(a.classId).time)),isToday=date.toDateString()===today.toDateString();return `<div class="calendar-day ${isToday?'today':''}" aria-label="${key}"><span class="calendar-number" ${isToday?'aria-current="date"':''}>${day}</span>${events.map(b=>`<div class="calendar-event"><strong>${classTitle(cl(b.classId))}</strong><span>${cl(b.classId).time}</span></div>`).join('')}</div>`}).join('')}</div></section>`}
function student(){if(tab==='join')return joinForm(true);if(tab==='courses'||tab==='catalog')return `<div class="row"><h1 class="title">${t('我的課程','My classes')}</h1><button data-go="/join">${t('報名課程','Join Class')}</button></div><div class="panel">${bookings(mine())}</div>`;if(tab==='payments')return `<h1 class="title">${t('付款及個人資料','Payments & profile')}</h1><div class="panel">${payments(mine(),false)}</div><section class="panel"><h2>${t('個人資料','Profile')}</h2><dl class="profile-details"><div><dt>${t('姓名','Name')}</dt><dd>${esc(db.student.name)}</dd></div><div><dt>${t('電話','Phone')}</dt><dd>${esc(db.student.phone)}</dd></div><div><dt>Email</dt><dd>${esc(db.student.email)}</dd></div></dl></section>`;return studentCalendar()}
function allStudentProfiles(){let others=[...new Set([...Object.keys(db.studentProfiles||{}),...db.bookings.filter(b=>b.studentId!=='demo'&&b.student!==db.student.name).map(b=>b.student)])].filter(n=>n!==db.student.name);return [{...db.student,id:'demo'},...others.map(n=>({name:n,phone:'00000000',email:'jamie@example.test',...(db.studentProfiles?.[n]||{}),id:n}))]}
function studentList(){return allStudentProfiles().filter(p=>db.bookings.some(b=>b.paid&&b.status==='confirmed'&&(p.id==='demo'?b.studentId==='demo'||b.student===p.name:b.student===p.name)))}
function editStudent(id){let person=allStudentProfiles().find(x=>x.id===id);if(!person)return;modal=`<div class="modal" role="dialog" aria-modal="true"><div class="dialog"><h2>${t('學生資料','Student details')}</h2><form id="teacher-profile" data-student="${esc(person.id)}" class="profile-editor"><label>${t('姓名','Name')}<input name="name" value="${esc(person.name)}" required></label><label>${t('電話','Phone')}<input name="phone" value="${esc(person.phone)}" required></label><label>Email<input name="email" type="email" value="${esc(person.email)}" required></label><div class="actions"><button>${t('儲存','Save')}</button><button type="button" class="ghost" data-action="close">${t('取消','Cancel')}</button></div></form></div></div>`;renderModal()}
function studentDirectory(){return `<div class="panel student-directory">${studentList().filter(p=>p.name.toLowerCase().includes(search.toLowerCase())).map(p=>`<div class="row"><div><strong>${esc(p.name)}</strong><p>${esc(p.phone)} · ${esc(p.email)}</p></div><button class="ghost" data-edit-student="${esc(p.id)}">${t('查看及修改','View & edit')}</button></div>`).join('')||`<p>${t('沒有符合的學生','No matching students')}</p>`}</div>`}
const weekdayName=d=>t('逢星期'+['日','一','二','三','四','五','六'][d],'Every '+['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d]);
const classNumber=c=>c.classCode||'CL-'+String(slotSeed.some(s=>s.id===c.id)?slotSeed.findIndex(s=>s.id===c.id)+1:c.id.replace(/^C/,'')).padStart(3,'0');
function classRoster(id){
  if(role!=='teacher')return missing();
  let c=cl(id);
  if(!c)return missing();
  let records=db.bookings.filter(b=>b.classId===id&&b.paid&&b.status==='confirmed');
  return `<button class="ghost list-back" data-action="back-classes">← ${t('返回班別','Back to classes')}</button><h1 class="title">${classTitle(c)} · ${t('學生名單','Students')}</h1><p class="class-number">${t('班別編號','Class code')}: ${esc(classNumber(c))} · ${slotText(c)}</p><section class="panel"><p>${t('學生人數','Students')}: ${records.length}</p>${records.length?`<div class="table-wrap"><table class="class-roster-table"><thead><tr><th>${t('學生姓名','Student name')}</th><th>${t('電話','Phone')}</th><th>Email</th></tr></thead><tbody>${records.map(b=>{let profile=b.studentId==='demo'&&b.student===db.student.name?db.student:db.studentProfiles?.[b.student]||{};return `<tr><td>${esc(b.student)}</td><td>${esc(profile.phone||b.phone||'—')}</td><td>${esc(profile.email||b.email||'—')}</td></tr>`}).join('')}</tbody></table></div>`:`<p class="empty">${t('此班別暫無已加入學生','No students have joined this class yet')}</p>`}</section>`;
}
function courseCodeFor(id){return db.courseCodes?.[id]||'CO-999'}
function nextCourseCode(){let i=1;while(Object.values(db.courseCodes||{}).some(code=>code.toUpperCase()==='CO-'+String(i).padStart(3,'0')))i++;return 'CO-'+String(i).padStart(3,'0')}
function courseImageMarkup(id){let list=db.classes.filter(c=>c.course===id),image=safeNewsImage(list.find(c=>safeNewsImage(c.image))?.image),index=courses.findIndex(c=>c.id===id);return image?`<img src="${image}" alt="${name(id)}">`:index>=0?photoContent(index):`<div class="course-board-placeholder">Sample</div>`}
function classSettings(){let groups=[...new Set(db.classes.map(c=>c.course))].sort((a,b)=>courseCodeFor(a).localeCompare(courseCodeFor(b),undefined,{numeric:true}));return `<div class="row class-settings-heading"><h1 class="title">${t('班別設定','Class settings')}</h1><button data-action="new-class">${t('新增課程','Add class')}</button></div><div class="class-settings-grid">${groups.map(id=>{let slots=db.classes.filter(c=>c.course===id).sort((a,b)=>classNumber(a).localeCompare(classNumber(b),undefined,{numeric:true}));return `<section class="panel course-board"><div class="course-board-heading"><div><span class="course-board-code">${esc(courseCodeFor(id))}</span><h2>${name(id)}</h2></div><button class="ghost class-pencil" data-edit-course="${esc(id)}" aria-label="${t('修改課程及時段','Edit course and times')} ${name(id)}"><svg viewBox="0 0 24 24" width="21" height="21" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true"><path d="m15 5 4 4M4 20l4-1L20 7a2.8 2.8 0 0 0-4-4L4 15z"/></svg></button></div><div class="course-board-photo">${courseImageMarkup(id)}</div><div class="course-board-slots">${slots.map(c=>`<article class="course-slot"><strong>${classDays(c).map(weekdayName).join(lang==='zh'?'、':', ')}</strong><p>${esc(c.time)}</p><p>${t('班別編號','Class number')}: ${esc(classNumber(c))}</p><p>${t('名額','Capacity')}: ${c.capacity}</p><p>${t('已佔名額','Occupied')}: ${c.occupied}</p><button class="ghost class-students-button" data-class-roster="${c.id}">${t('查看學生名單','View students')}</button></article>`).join('')}</div></section>`}).join('')}</div>`}

function nextClassCode(){let i=1;while(db.classes.some(c=>classNumber(c).toUpperCase()==='CL-'+String(i).padStart(3,'0')))i++;return 'CL-'+String(i).padStart(3,'0')}
const classPhotoRatio=8/5;
let classCropDrag=null;
function cropHeight(crop){return crop.width*crop.aspect/classPhotoRatio}
function initialClassCrop(width,height){let aspect=width/height,maxWidth=Math.min(.9,.9*classPhotoRatio/aspect),cropWidth=maxWidth*.8,cropHeight=cropWidth*aspect/classPhotoRatio;return {aspect,width:cropWidth,x:(1-cropWidth)/2,y:(1-cropHeight)/2}}
function clampCrop(value,min,max){return Math.min(max,Math.max(min,value))}
function resizeClassCrop(width){if(!classCrop)return;let oldCenterX=classCrop.x+classCrop.width/2,oldCenterY=classCrop.y+cropHeight(classCrop)/2,maxWidth=Math.min(.98,.98*classPhotoRatio/classCrop.aspect),minWidth=Math.min(.15,maxWidth/2);classCrop.width=clampCrop(width,minWidth,maxWidth);classCrop.x=clampCrop(oldCenterX-classCrop.width/2,0,1-classCrop.width);classCrop.y=clampCrop(oldCenterY-cropHeight(classCrop)/2,0,1-cropHeight(classCrop));updateClassCropFrame()}
function classCropMarkup(){if(!classCropSource||!classCrop)return '';return `<div class="class-crop-editor"><p>${t('拖動裁切框，拉動右下角調整大小。相片將以固定 8:5 比例顯示。','Drag the crop frame and its bottom-right corner to choose the photo. The 8:5 shape stays fixed.')}</p><div id="class-crop-stage" class="class-crop-stage" style="aspect-ratio:${classCrop.aspect};max-width:${Math.min(460,420*classCrop.aspect)}px"><img src="${classCropSource}" alt="${t('待裁切課程照片','Class photo to crop')}" draggable="false"><div id="class-crop-frame" class="class-crop-frame" style="left:${classCrop.x*100}%;top:${classCrop.y*100}%;width:${classCrop.width*100}%;height:${cropHeight(classCrop)*100}%" tabindex="0" role="group" aria-label="${t('拖動以選擇裁切位置','Drag to choose crop position')}"><span class="class-crop-handle" aria-hidden="true"></span></div></div><label class="class-crop-size">${t('裁切範圍大小','Crop size')}<input id="class-crop-size" type="range" min="15" max="100" value="${Math.round(classCrop.width/Math.min(.98,.98*classPhotoRatio/classCrop.aspect)*100)}"></label><button type="button" data-action="apply-class-crop">${t('套用裁切','Apply crop')}</button></div>`}
function updateClassCropFrame(){let frame=document.querySelector('#class-crop-frame');if(!frame||!classCrop)return;frame.style.left=classCrop.x*100+'%';frame.style.top=classCrop.y*100+'%';frame.style.width=classCrop.width*100+'%';frame.style.height=cropHeight(classCrop)*100+'%'}
function applyClassCrop(){if(!classCropSource||!classCrop)return true;let image=document.querySelector('#class-crop-stage img'),canvas=document.createElement('canvas');if(!image?.naturalWidth||!image?.naturalHeight||!canvas.getContext)return false;canvas.width=800;canvas.height=500;let context=canvas.getContext('2d');if(!context)return false;context.drawImage(image,classCrop.x*image.naturalWidth,classCrop.y*image.naturalHeight,classCrop.width*image.naturalWidth,cropHeight(classCrop)*image.naturalHeight,0,0,800,500);classDraftImage=canvas.toDataURL('image/jpeg',.85);classCropSource='';classCrop=null;document.querySelector('#class-crop-editor').innerHTML='';document.querySelector('#class-image-preview').innerHTML=`<img src="${classDraftImage}" alt="${t('課程照片預覽','Class photo preview')}">`;return true}
function editClass(id=''){if(role!=='teacher')return;let c=id?cl(id):{course:'art',weekday:1,time:'09:00',capacity:8,occupied:0,lessonsPerTerm:4};if(!c)return;classDraftImage=safeNewsImage(c.image);classCropSource='';classCrop=null;modal=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="class-editor-title"><div class="dialog"><h2 id="class-editor-title">${id?t('修改課程','Edit class'):t('新增課程','Add class')}</h2><form id="class-editor" class="profile-editor" data-id="${id}"><label>${t('課程','Course')}<input name="courseName" value="${id?classTitle(c):''}" required></label><label>Class code<input name="classCode" value="${esc(id?classNumber(c):nextClassCode())}" required></label><fieldset class="weekday-options"><legend>${t('星期','Weekday')}</legend>${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="weekdays" value="${d}" ${classDays(c).includes(d)?'checked':''}><span>${weekdayName(d)}</span></label>`).join('')}</fieldset><label>${t('時間','Time')}<input type="time" name="time" value="${c.time}" required></label><label>${t('每期堂數','Lessons per term')}<input type="number" name="lessonsPerTerm" min="1" max="52" step="1" value="${termLessons(c)}" required></label><label>${t('名額','Capacity')}<input type="number" name="capacity" min="${Math.max(1,c.occupied)}" step="1" value="${c.capacity}" required></label><label>${t('課程照片','Class photo')}<input id="class-image" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="news-upload-note">${t('圖片格式：JPG、PNG 或 WebP，最大 1 MB。','Image formats: JPG, PNG or WebP. Maximum 1 MB.')}</p><div id="class-image-preview" class="news-image-preview">${classDraftImage?`<img src="${classDraftImage}" alt="${t('課程照片預覽','Class photo preview')}">`:''}</div><div id="class-crop-editor">${classCropMarkup()}</div><p id="class-error" class="error" role="alert"></p><div class="actions"><button type="button" class="ghost" data-action="close">${t('取消','Cancel')}</button><button>${id?t('確認修改','Confirm changes'):t('新增課程','Add class')}</button></div></form></div></div>`;renderModal()}

let courseDraftSlot=0;
function courseSlotEditor(c,key,expanded=false){let days=classDays(c),summary=`${days.map(weekdayName).join(lang==='zh'?'、':', ')} · ${c.time} · ${esc(c.classCode||classNumber(c))}`;return `<details class="course-slot-editor" data-slot-id="${key}" ${expanded?'open':''}><summary>${summary}</summary><div class="course-slot-body"><label>Class code<input name="classCode.${key}" value="${esc(c.classCode||classNumber(c))}"></label><fieldset class="weekday-options"><legend>${t('星期','Weekday')}</legend>${[1,2,3,4,5,6,0].map(d=>`<label><input type="checkbox" name="weekdays.${key}" value="${d}" ${days.includes(d)?'checked':''}><span>${weekdayName(d)}</span></label>`).join('')}</fieldset><div class="course-slot-fields"><label>${t('時間','Time')}<input type="time" name="time.${key}" value="${c.time}"></label><label>${t('名額','Capacity')}<input type="number" name="capacity.${key}" min="${Math.max(1,c.occupied||0)}" step="1" value="${c.capacity}"></label><label>${t('每期堂數','Lessons per term')}<input type="number" name="lessonsPerTerm.${key}" min="1" max="52" step="1" value="${termLessons(c)}"></label></div></div></details>`}
function nextDraftClassCode(){let used=[...document.querySelectorAll('#course-editor input[name^="classCode."]')].map(input=>input.value.toLowerCase()),i=1;while(used.includes('cl-'+String(i).padStart(3,'0'))||db.classes.some(c=>classNumber(c).toLowerCase()==='cl-'+String(i).padStart(3,'0')))i++;return 'CL-'+String(i).padStart(3,'0')}
function editCourse(courseId){if(role!=='teacher')return;let slots=db.classes.filter(c=>c.course===courseId).sort((a,b)=>classNumber(a).localeCompare(classNumber(b),undefined,{numeric:true}));if(!slots.length)return;classDraftImage=safeNewsImage(slots.find(c=>safeNewsImage(c.image))?.image);classCropSource='';classCrop=null;courseDraftSlot=0;let index=courses.findIndex(c=>c.id===courseId);modal=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="course-editor-title"><div class="dialog course-editor-dialog"><h2 id="course-editor-title">${t('修改課程及時段','Edit course and times')}</h2><form id="course-editor" class="profile-editor" data-course="${esc(courseId)}"><div class="course-shared-fields"><label>${t('課程名稱','Course name')}<input name="courseName" value="${name(courseId)}" required></label><label>Course code<input name="courseCode" value="${esc(courseCodeFor(courseId))}" required></label></div><label>${t('更換課程照片','Replace class photo')}<input id="class-image" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="news-upload-note">${t('圖片格式：JPG、PNG 或 WebP，最大 1 MB。','Image formats: JPG, PNG or WebP. Maximum 1 MB.')}</p><p class="existing-photo-label">${t('目前照片','Current photo')}</p><div id="class-image-preview" class="news-image-preview">${classDraftImage?`<img src="${classDraftImage}" alt="${t('課程照片預覽','Class photo preview')}">`:index>=0?photoContent(index):''}</div><div id="class-crop-editor"></div><h3>${t('班別時段','Class times')}</h3><div id="course-slot-fields">${slots.map((c,index)=>courseSlotEditor(c,c.id,index===0)).join('')}</div><button type="button" class="ghost" data-action="add-course-slot">+ ${t('新增時段','Add time slot')}</button><p id="course-error" class="error" role="alert"></p><div class="actions"><button type="button" class="ghost" data-action="close">${t('取消','Cancel')}</button><button>${t('確認修改','Confirm changes')}</button></div></form></div></div>`;renderModal()}
function courseRows(fields){let values=Object.fromEntries(fields),keys=[...new Set(fields.filter(([key])=>key.startsWith('classCode.')).map(([key])=>key.slice(10)))];return keys.map(id=>({id,classCode:String(values['classCode.'+id]||'').trim(),weekdays:[...new Set(fields.filter(([key])=>key==='weekdays.'+id).map(([,value])=>Number(value)))],time:String(values['time.'+id]||''),capacity:Number(values['capacity.'+id]),lessonsPerTerm:Number(values['lessonsPerTerm.'+id])}))}
function courseEditorError(courseId,courseName,courseCode,rows){
 if(!courseName||!courseCode||!rows.length)return t('請填寫課程名稱、Course code 和時段。','Enter a course name, course code and at least one time slot.');
 if(!/^[A-Za-z0-9-]+$/.test(courseCode)||Object.entries(db.courseCodes||{}).some(([id,code])=>id!==courseId&&code.toLowerCase()===courseCode.toLowerCase()))return t('Course code 格式不正確或已被使用。','Course code is invalid or already in use.');
 if(db.classes.some(c=>c.course!==courseId&&String(c.courseName||courses.find(x=>x.id===c.course)?.e||c.course).toLowerCase()===courseName.toLowerCase()))return t('另一課程已使用此名稱。','Another course already uses this name.');
 let existing=db.classes.filter(c=>c.course===courseId),other=db.classes.filter(c=>c.course!==courseId),keys=new Set(rows.map(row=>row.id));
 if(existing.some(c=>!keys.has(c.id))||rows.some(row=>!row.id.startsWith('new-')&&!existing.some(c=>c.id===row.id)))return t('班別資料有誤，請重新開啟編輯。','Class data changed. Reopen the editor.');
 let codes=other.map(c=>classNumber(c).toLowerCase());
 for(let row of rows){let original=cl(row.id);if(!row.classCode||!row.weekdays.length||row.weekdays.some(d=>!Number.isInteger(d)||d<0||d>6)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(row.time)||!Number.isInteger(row.capacity)||row.capacity<Math.max(1,original?.occupied||0)||!Number.isInteger(row.lessonsPerTerm)||row.lessonsPerTerm<1||row.lessonsPerTerm>52)return t('請檢查每個時段的星期、時間、名額、每期堂數和 Class code。','Check the weekdays, time, capacity, lessons per term and class code for every time slot.');let code=row.classCode.toLowerCase();if(codes.includes(code))return t('Class code 已被使用，請輸入其他編號。','Class code is already in use. Enter a different code.');codes.push(code)}
 let times=other.map(c=>({weekdays:classDays(c),time:c.time}));for(let row of rows){if(times.some(c=>c.time===row.time&&c.weekdays.some(d=>row.weekdays.includes(d))))return t('這個時段已有課程，請選擇其他星期或時間。','Another class uses this time. Choose a different weekday or time.');times.push(row)}return ''
}

function teacherNews(){let posts=[...(db.news||[])].sort((a,b)=>b.releaseDate.localeCompare(a.releaseDate)),editing=posts.find(post=>post.id===newsEditId);return `<div class="news-manager-heading"><h1 class="title">${t('消息管理','News')}</h1><p>${t('發布和更新網站上的畫室消息。','Publish and update studio news on the website.')}</p></div><section class="section teacher-news-section"><div class="row teacher-news-heading"><h2>${t('已發布消息','Published news')}</h2><button data-action="new-news">${t('新增消息','Add news')}</button></div><div class="teacher-news-list">${posts.map(post=>`<article><img src="${newsPostImage(post.image)||'/assets/beamal-art.jpg'}" alt=""><div><time datetime="${post.releaseDate}">${upcomingDate(post.releaseDate)}</time><h3>${esc(newsPostText(post,'title'))}</h3><p>${esc(newsPostText(post,'description'))}</p></div><button class="ghost" data-edit-news="${esc(post.id)}">${t('編輯','Edit')}</button></article>`).join('')||`<p class="empty">${t('尚未發布消息','No published news yet')}</p>`}</div></section><section class="panel news-manager-editor"><h2>${editing?t('編輯消息','Edit news'):t('新增消息','Add news')}</h2><form id="teacher-news" class="news-editor" data-news-id="${esc(editing?.id||'')}"><label>${t('標題','Title')}<input name="title" maxlength="120" value="${esc(editing?newsPostText(editing,'title'):'')}" required></label><label>${t('簡介','Description')}<textarea name="description" rows="3" maxlength="280" required>${esc(editing?newsPostText(editing,'description'):'')}</textarea></label><label>${t('內文','Content')}<textarea name="content" rows="6" required>${esc(editing?newsPostText(editing,'content'):'')}</textarea></label><label>${t('發布日期','Release date')}<input type="date" name="releaseDate" value="${esc(editing?.releaseDate||localToday())}" required></label><label>${t('上載圖片','Upload image')}<input id="teacher-news-image" type="file" accept="image/jpeg,image/png,image/webp"></label><p class="news-upload-note">${t('圖片格式：JPG、PNG 或 WebP，最大 1 MB。','Image formats: JPG, PNG or WebP. Maximum 1 MB.')}</p><div id="news-image-preview" class="news-image-preview">${newsPostImage(newsDraftImage)?`<img src="${newsDraftImage}" alt="${t('圖片預覽','Image preview')}">`:''}</div><p id="teacher-news-error" class="error" role="alert"></p><div class="news-editor-actions"><button type="submit">${editing?t('儲存修改','Save changes'):t('發布消息','Publish news')}</button>${editing?`<button type="button" class="ghost" data-action="cancel-news-edit">${t('取消','Cancel')}</button>`:''}</div></form></section>`}
const managementPermissions=[['classes','班別與課程','Classes & courses'],['students','學生名單','Student lists'],['payments','收款與收入','Payments & income'],['news','消息管理','News'],['management','老師管理','Teacher management']];
const previewTeachers=[{id:'manager',name:'Teacher 1',level:'manager',permissions:managementPermissions.map(([id])=>id)},{id:'teacher2',name:'Teacher 2',level:'teacher',permissions:['classes','students']}];
function managementPage(){return `<div class="row management-heading"><div><h1 class="title">${t('老師管理','Management')}</h1><p class="sub">${t('查看老師及其權限級別','Review teacher roles and access')}</p></div><button data-action="add-teacher">${t('新增老師','Add teacher')}</button></div><div class="management-list">${previewTeachers.map(person=>`<section class="panel management-teacher"><div><h2>${person.name}</h2><span class="role-badge">${person.level==='manager'?t('管理員','Manager'):t('老師','Teacher')}</span>${person.id==='teacher2'?`<span class="preview-badge">${t('介面預覽','Preview')}</span>`:''}</div><button class="ghost" data-preview-teacher="${person.id}">${t('查看權限','View access')}</button></section>`).join('')}</div>`}
function openTeacherManagement(id=''){if(role!=='teacher')return;let person=previewTeachers.find(item=>item.id===id),permissions=person?.permissions||['classes','students'];modal=`<div class="modal" role="dialog" aria-modal="true" aria-labelledby="management-title"><div class="dialog"><h2 id="management-title">${person?t('老師權限','Teacher access'):t('新增老師','Add teacher')}</h2><p class="notice">${t('此介面只供討論。正式老師帳戶、權限和啟用方法有待確認；這裡不會建立或修改帳戶。','This is a preview for discussion. Teacher accounts, access rules and activation will be agreed later. Nothing is created or changed here.')}</p><form id="management-preview" class="profile-editor"><label>${t('老師姓名','Teacher name')}<input name="name" value="${esc(person?.name||'')}" placeholder="Teacher name"></label><label>Email<input name="email" type="email" value="" placeholder="teacher@example.test"></label><label>${t('權限級別','Access level')}<select name="level"><option value="teacher" ${person?.level==='teacher'?'selected':''}>${t('老師','Teacher')}</option><option value="manager" ${person?.level==='manager'?'selected':''}>${t('管理員','Manager')}</option></select></label><fieldset class="permission-options"><legend>${t('可使用功能','Available sections')}</legend>${managementPermissions.map(([key,z,e])=>`<label><input type="checkbox" name="permission" value="${key}" ${permissions.includes(key)?'checked':''}><span>${t(z,e)}</span></label>`).join('')}</fieldset><p id="management-preview-note" class="management-preview-note" role="status"></p><div class="actions"><button type="submit">${person?t('儲存權限','Save access'):t('建立帳戶','Create account')}</button><button type="button" class="ghost" data-action="close">${t('關閉','Close')}</button></div></form></div></div>`;renderModal()}
function teacher(){if(path().startsWith('/account/classes/'))return classRoster(path().split('/')[3]);if(tab==='student-list')return `<button class="ghost list-back" data-tab="overview">← ${t('返回時間表','Back to timetable')}</button><h1 class="title">${t('學生名單','Students')}</h1><input id="search" placeholder="${t('搜尋學生姓名','Search students')}" value="${esc(search)}">${studentDirectory()}`;if(tab==='new-enrolments')return `<button class="ghost list-back" data-tab="overview">← ${t('返回時間表','Back to timetable')}</button><h1 class="title">${t('新學生報名','New student enrolments')}</h1><div class="panel">${bookings(newEnrolments(),true)}</div>`;if(tab==='students')return classSettings();if(tab==='payments')return incomePage();if(tab==='news')return teacherNews();if(tab==='management')return managementPage();let today=localToday();return `${stats()}<section class="panel teacher-today"><div class="teacher-today-heading"><h2>${t('今日課堂','Classes today')}</h2><time datetime="${today}">${today}</time></div><div class="teacher-today-list">${sortedClasses(db.classes.filter(c=>classDays(c).includes(new Date().getDay()))).map(c=>`<div class="teacher-today-row"><span>${classTitle(c)}</span><time>${c.time}</time></div>`).join('')||`<p>${t('今日沒有課堂；下次課堂見班別列表。','No classes today; see the class list for upcoming times.')}</p>`}</div></section>`}
