// Keep the existing page mounted so the sidebar transition preserves drafts and focus.
function syncPortalMenu(){
  if(!isAccountPage())return;
  let shell=document.querySelector('.portal-shell'),sidebar=document.querySelector('#portal-sidebar'),button=document.querySelector('[data-action="portal-menu"]');
  if(!shell||!sidebar||!button)return;
  let mobile=portalViewport?.matches||false;
  shell.classList.toggle('is-menu-open',portalMenu);
  sidebar.inert=mobile&&!portalMenu;
  button.setAttribute('aria-expanded',String(mobile?portalMenu:!portalMenu));
}
