const courseSettingsFor=id=>db.courseSettings.find(c=>c.id===id);
const allCourseIds=()=>[...new Set([...db.classes.map(c=>c.course),...db.courseSettings.map(c=>c.id)])];
const rawCourseName=id=>db.classes.find(c=>c.course===id)?.courseName||courseSettingsFor(id)?.courseName||courses.find(c=>c.id===id)?.e||id;
function coursePriceDescription(c){
 if(c.pricingModel==='monthly-lessons')return t(`每堂 · ${c.duration} 分鐘 · ${c.months} 個月`,`per lesson · ${c.duration} min · ${c.months} ${c.months===1?'month':'months'}`);
 if(c.pricingModel==='fixed-monthly')return t(`每月 · ${c.months} 個月`,`per month · ${c.months} ${c.months===1?'month':'months'}`);
 return t(`套票 · 共 ${c.packageTotal} ${c.packageType==='minutes'?'分鐘':'堂'}`,`package · ${c.packageTotal} ${c.packageType==='minutes'?'minutes':'lessons'} in total`);
}
function courseFormField(label,control,extra=''){return `<label class="create-course-field ${extra}"><span>${label}</span>${control}</label>`}
function coursePricingHelp(id,z,e){return `<details class="course-pricing-help"><summary aria-label="${t('收費模式說明','Pricing model information')}" aria-describedby="${id}-help">i</summary><div id="${id}-help" role="tooltip">${t(z,e)}</div></details>`}
function openCreateCourse(id=''){
 if(role!=='teacher')return;
 let c=id?courseSettingsFor(id):null;if(id&&!c)return;
 c=c||{courseName:'',category:'',level:'',feeName:'',pricingModel:'monthly-lessons',price:'',duration:'',months:1,packageType:'minutes',packageTotal:'',bookingExpiry:null,onlineStore:false};
 let field=courseFormField,options=(values)=>[...new Set(values.filter(Boolean))].map(v=>`<option value="${esc(v)}"></option>`).join('');
 let combobox=(label,key,list,values,required=false)=>field(label,`<input name="${key}" list="${list}" value="${esc(c[key])}" maxlength="200" autocomplete="off" ${required?'required':''}><datalist id="${list}">${options(values)}</datalist>`,'course-combobox');
 let amount=(label,key,model,extra='')=>field(label,`<span class="course-money-input"><span aria-hidden="true">$</span><input type="number" name="${key}" min="0.01" step="0.01" value="${c.pricingModel===model?esc(c.price):''}" required></span>`,extra);
 let months=key=>field(t('月數','No. of months'),`<select name="${key}">${Array.from({length:12},(_,i)=>i+1).map(n=>`<option value="${n}" ${n===c.months?'selected':''}>${t(n+' 個月',n+' '+(n===1?'month':'months'))}</option>`).join('')}</select>`);
 let mode=(key,z,e,helpZ,helpE,fields)=>`<div class="course-pricing-option"><div class="course-pricing-option-title"><label><input type="radio" name="pricingModel" value="${key}" ${c.pricingModel===key?'checked':''}><span>${t(z,e)}</span></label>${coursePricingHelp(key,helpZ,helpE)}</div><fieldset class="course-pricing-fields" data-pricing-fields="${key}" ${c.pricingModel===key?'':'hidden disabled'}><legend class="sr-only">${t(z,e)}</legend>${fields}</fieldset></div>`;
 modal=`<div class="modal create-course-modal" role="dialog" aria-modal="true" aria-labelledby="create-course-title"><div class="dialog create-course-dialog"><header class="create-course-header"><h2 id="create-course-title">${id?t('修改課程','Edit course'):t('新增課程','Create course')}</h2><button type="button" data-action="close" aria-label="${t('關閉','Close')}">×</button></header><form id="create-course-editor" data-id="${esc(id)}"><div class="create-course-body"><section><h3>${t('課程概覽','Course overview')}</h3>${combobox(t('課程名稱 *','Course name *'),'courseName','create-course-names',allCourseIds().map(rawCourseName),true)}<div class="course-form-two">${combobox(t('類別（可選）','Category (optional)'),'category','create-course-categories',db.courseSettings.map(c=>c.category))}${combobox(t('程度（可選）','Level (optional)'),'level','create-course-levels',db.courseSettings.map(c=>c.level))}</div></section><section><h3>${t('收費','Pricing')}</h3>${combobox(t('費用名稱 *','Fee name *'),'feeName','create-course-fees',db.courseSettings.map(c=>c.feeName),true)}<p class="course-pricing-caption">${t('收費模式','Pricing model')}</p><div class="course-pricing-models">
 ${mode('monthly-lessons','按當月堂數計算月費','Monthly fee according to number of lessons in a month','例如：每堂 60 分鐘，收費 $300；當月有 5 堂，月費為 $300 × 5 = $1,500。','E.g. 60 minutes per lesson at $300. If a student attends 5 Mondays in a month, the monthly fee is $300 × 5 = $1,500.',amount(t('每堂費用','Price per lesson'),'lessonPrice','monthly-lessons')+field(t('每堂時長（分鐘）','Duration per lesson (minutes)'),`<input type="number" name="duration" min="1" step="1" value="${esc(c.duration??'')}" required>`)+months('lessonMonths'))}
 ${mode('fixed-monthly','固定月費，不受當月堂數影響','Fixed monthly fee, no matter how many lessons in a month','例如：固定月費 $300；學生逢星期一上課，不論當月有多少個星期一，月費都是 $300。','E.g. a fixed monthly fee of $300. A student attending every Monday pays $300 for the month, regardless of the number of Mondays.',amount(t('固定月費','Fixed monthly price'),'monthlyPrice','fixed-monthly')+months('fixedMonths'))}
 ${mode('package','固定堂數套票','Package with fixed number of lessons','例如：4 堂、每堂 60 分鐘的套票共 $300；每星期一上課，由 8 月中開始，完成 4 堂後約於 9 月中結束。','E.g. 4 lessons of 60 minutes for $300 in total. A student starting in mid-August and attending every Monday finishes after 4 lessons in mid-September.',amount(t('套票費用','Package price'),'packagePrice','package','course-form-full')+field(t('計算單位','Type'),`<select name="packageType"><option value="minutes" ${c.packageType==='minutes'?'selected':''}>${t('分鐘','Minutes')}</option><option value="lessons" ${c.packageType==='lessons'?'selected':''}>${t('堂數','Lessons')}</option></select>`)+field(`<span id="package-total-label">${c.packageType==='lessons'?t('總堂數','Lessons in total'):t('總分鐘數','Minutes in total')}</span>`,`<input type="number" name="packageTotal" min="1" step="1" value="${esc(c.packageTotal??'')}" required>`))}
 </div></section><section class="course-expiry-section"><div class="course-expiry-heading"><h3>${t('預約期限（由發票日期起計）','Booking expiry (from invoice date)')}</h3><label class="course-switch"><input type="checkbox" name="expiryEnabled" ${c.bookingExpiry?'checked':''}><span class="course-switch-track" aria-hidden="true"></span><span>${t('啟用','Enable')}</span></label></div><p class="course-expiry-description">${t('啟用後，學生不能在到期日後向訂單加入額外課堂。','When enabled, students cannot add additional lessons into the order after the expiry date.')}</p><fieldset id="course-expiry-fields" class="course-expiry-fields" ${c.bookingExpiry?'':'disabled'}><legend class="sr-only">${t('預約有效期','Booking validity')}</legend>${field(t('有效期','Valid for'),`<input type="number" name="expiryValue" min="1" step="1" value="${esc(c.bookingExpiry?.value??'')}" required>`)}${field(t('單位','Unit'),`<select name="expiryUnit">${[['days','日'],['weeks','星期'],['months','月']].map(([unit,z])=>`<option value="${unit}" ${(c.bookingExpiry?.unit||'months')===unit?'selected':''}>${t(z,unit)}</option>`).join('')}</select>`)}</fieldset></section><section><h3>${t('網上商店','Online Store')}</h3><label class="course-switch"><input type="checkbox" name="onlineStore" ${c.onlineStore?'checked':''}><span class="course-switch-track" aria-hidden="true"></span><span>${t('顯示於網上商店','Display in Online Store')}</span></label></section><p id="create-course-error" class="error" role="alert"></p></div><footer class="create-course-footer"><button type="button" class="ghost" data-action="close">${t('取消','Cancel')}</button><button type="submit">${id?t('儲存','Save'):t('建立','Create')}</button></footer></form></div></div>`;
 renderModal();document.querySelector('#create-course-editor [name=courseName]').focus();
}
function syncCoursePricing(form){
 let model=form.querySelector('[name=pricingModel]:checked').value;
 for(let fields of form.querySelectorAll('[data-pricing-fields]')){let active=fields.dataset.pricingFields===model;fields.hidden=!active;fields.disabled=!active}
 form.querySelector('#course-expiry-fields').disabled=!form.querySelector('[name=expiryEnabled]').checked;
 form.querySelector('#package-total-label').textContent=form.querySelector('[name=packageType]').value==='lessons'?t('總堂數','Lessons in total'):t('總分鐘數','Minutes in total');
}
function saveCourseSettings(data,id=''){
 if(role!=='teacher')return;
 let current=id?courseSettingsFor(id):null;if(id&&!current)return;
 let courseName=String(data.courseName||'').trim(),feeName=String(data.feeName||'').trim(),model=String(data.pricingModel||''),price=Number(data[{'monthly-lessons':'lessonPrice','fixed-monthly':'monthlyPrice',package:'packagePrice'}[model]]),months=Number(data[model==='fixed-monthly'?'fixedMonths':'lessonMonths']),duration=Number(data.duration),packageTotal=Number(data.packageTotal),error='';
 const positiveInteger=n=>Number.isSafeInteger(n)&&n>0;
 if(!courseName||!feeName||courseName.length>200||feeName.length>200)error=t('請填寫課程名稱及費用名稱。','Enter a course name and fee name.');
 else if(allCourseIds().some(other=>other!==id&&rawCourseName(other).toLowerCase()===courseName.toLowerCase()))error=t('此課程名稱已被使用，請輸入其他名稱。','This course name is already in use. Enter a different name.');
 else if(!['monthly-lessons','fixed-monthly','package'].includes(model)||!Number.isFinite(price)||price<=0)error=t('請選擇收費模式，並輸入大於零的費用。','Choose a pricing model and enter a price greater than zero.');
 else if(model!=='package'&&(!positiveInteger(months)||months>12))error=t('請選擇 1 至 12 個月。','Choose between 1 and 12 months.');
 else if(model==='monthly-lessons'&&!positiveInteger(duration))error=t('請輸入大於零的每堂時長（整數分鐘）。','Enter a positive whole number of minutes per lesson.');
 else if(model==='package'&&(!['minutes','lessons'].includes(data.packageType)||!positiveInteger(packageTotal)))error=t('請選擇套票單位，並輸入大於零的總數。','Choose a package type and enter a positive whole-number total.');
 else if(data.expiryEnabled&&(!positiveInteger(Number(data.expiryValue))||!['days','weeks','months'].includes(data.expiryUnit)))error=t('請輸入有效的預約期限及單位。','Enter a valid booking expiry and unit.');
 if(error){document.querySelector('#create-course-error').textContent=error;return}
 let record={id:current?.id||'course-'+db.next++,courseName,feeName,category:String(data.category||'').trim().slice(0,200),level:String(data.level||'').trim().slice(0,200),pricingModel:model,price,...(model==='package'?{packageType:data.packageType,packageTotal}:{months,...(model==='monthly-lessons'?{duration}:{})}),bookingExpiry:data.expiryEnabled?{value:Number(data.expiryValue),unit:data.expiryUnit}:null,onlineStore:!!data.onlineStore};
 if(current)db.courseSettings[db.courseSettings.indexOf(current)]=record;else db.courseSettings.push(record);
 db.courseCodes[record.id]??=nextCourseCode();
 for(let c of db.classes.filter(c=>c.course===record.id))c.courseName=courseName;
 save();modal='';courseSearch='';tab='catalog';render();toast(t('課程已儲存','Course saved'));
}
document.addEventListener('change',e=>{let form=e.target.closest?.('#create-course-editor');if(form&&['pricingModel','expiryEnabled','packageType'].includes(e.target.name))syncCoursePricing(form)});
