function scheduleResourceOptions(kind){let stored=kind==='teacher'?previewTeachers.map(p=>p.name):[],values=[...stored,...db.classes.map(c=>c[kind]),...db.schedules.map(s=>s[kind])];return [...new Set(values.filter(Boolean).map(String))].sort()}
