 let combo=(key,z,e)=>courseFormField(t(z,e),`<input name="${key}" value="${esc(lead[key])}" maxlength="200" list="lead-${key}-values"><datalist id="lead-${key}-values">${[...new Set(db.leads.map(lead=>lead[key]).filter(Boolean))].map(value=>`<option value="${esc(value)}"></option>`).join('')}</datalist>`,'lead-field course-combobox');
 modal=`<div class="modal create-course-modal lead-editor-modal" role="dialog" aria-modal="true" aria-labelledby="lead-editor-title"><div class="dialog create-course-dialog lead-editor-dialog"><header class="create-course-header"><h2 id="lead-editor-title">${id?t('修改潛在客戶','Edit lead'):t('新增潛在客戶','Create lead')}</h2><button type="button" data-action="close" aria-label="${t('關閉','Close')}">×</button></header><form id="lead-editor" data-id="${esc(id)}"><div class="create-course-body lead-editor-body"><section><h3>${t('個人資料','Personal information')}</h3><div class="lead-personal-layout"><div class="lead-personal-fields"><div class="lead-form-three">${field('displayName','顯示名稱 *','Display name *','text',true)}${field('studentNumber','學生編號','Student no.','text',false,true)}${field('citizenId','身份證號碼','Citizen ID')}${field('firstName','名字','First name')}${field('lastName','姓氏','Last name')}${field('fullName','全名','Full name')}${field('localName','中文姓名','Local name')}${select('gender','性別','Gender',[['','',''],['female','女','Female'],['male','男','Male'],['other','其他','Other'],['unspecified','不提供','Prefer not to say']])}${field('birthDate','出生日期','Date of birth','date')}</div><div class="lead-form-divider"></div><div class="lead-form-three">${field('email','電郵','Email','email')}${select('promotion','接收推廣電郵','Receive promotional email',[['yes','是','Yes'],['no','否','No']])}<div class="lead-form-spacer"></div>${field('phone','電話','Phone','tel')}${field('mobile','手提電話','Mobile','tel')}<div class="lead-form-spacer"></div>${field('address','地址','Address')}${select('district','地區','District',[['','',''],['hk','香港島','Hong Kong Island'],['kowloon','九龍','Kowloon'],['nt','新界','New Territories']])}<div class="lead-form-spacer"></div>${[1,2].map(n=>field(`contact${n}Name`,`聯絡人 ${n} 姓名`,`Name (Contact ${n})`)+field(`contact${n}Phone`,`聯絡人 ${n} 電話`,`Phone (Contact ${n})`,'tel')+field(`contact${n}Email`,`聯絡人 ${n} 電郵`,`Email (Contact ${n})`,'email')).join('')}</div><div class="lead-form-divider"></div><div class="lead-form-three">${combo('school','學校','School')}${combo('level','程度','Level')}${field('occupation','職業','Occupation')}${field('enrolmentDate','入學日期','Enrollment date','date',false,true)}${field('quitDate','離校日期','Quit date','date',false,true)}<div class="lead-form-spacer"></div>${field('detail','詳細資料','Detail')}${field('remark','備註','Remark')}<div class="lead-form-spacer"></div>${field('billName','賬單名稱','Bill name','text',false,true)}${courseFormField(t('建立來源','Created Source'),`<input value="${t('手動新增','Manual')}" disabled>`,'lead-field')}<div class="lead-form-spacer"></div></div></div><div class="lead-avatar" aria-label="${t('個人照片預留位置','Profile photo placeholder')}"><svg viewBox="0 0 100 100" aria-hidden="true"><circle cx="50" cy="30" r="18"/><path d="M14 88V74c0-27 72-27 72 0v14Z"/></svg></div></div></section><section class="lead-information"><h3>${t('潛在客戶資料','Lead information')}</h3><div class="lead-form-three">${select('stage','跟進階段','Stage',leadStages)}${select('owner','負責人','Owner',[['','',''],...previewTeachers.map(person=>[person.name,person.name,person.name])])}${field('marketingSource','推廣來源','Marketing source')}</div>${courseFormField(t('跟進留言','Comments'),`<textarea name="comments" rows="5" maxlength="4000" placeholder="${t('輸入留言','Input comment')}">${esc(lead.comments)}</textarea>`,'lead-field lead-comments')}</section><p id="lead-editor-error" class="error" role="alert"></p></div><footer class="create-course-footer"><button type="button" class="ghost" data-action="close">${t('取消','Cancel')}</button><button type="submit">${id?t('儲存','Save'):t('建立','Create')}</button></footer></form></div></div>`;renderModal();document.querySelector('#lead-editor [name=displayName]').focus();
