function saveLead(data,id=''){
 if(role!=='teacher')return;let current=id?db.leads.find(lead=>lead.id===id):null;if(id&&!current)return;let fields=['displayName','citizenId','firstName','lastName','fullName','localName','birthDate','email','phone','mobile','address','contact1Name','contact1Phone','contact1Email','contact2Name','contact2Phone','contact2Email','school','level','occupation','detail','remark','marketingSource','comments'],record=Object.fromEntries(fields.map(key=>[key,String(data[key]||'').trim()])),error='';
 if(!record.displayName)error=t('請填寫顯示名稱。','Enter a display name.');
 else if(fields.some(key=>record[key].length>(key==='comments'?4000:200)))error=t('資料過長，請縮短後再儲存。','Some information is too long. Shorten it before saving.');
 else if(['email','contact1Email','contact2Email'].some(key=>record[key]&&!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(record[key])))error=t('請輸入有效的電郵地址。','Enter a valid email address.');
 else if(record.birthDate&&(!validISODate(record.birthDate)||record.birthDate>localToday()))error=t('請輸入有效的出生日期。','Enter a valid date of birth.');
 else if(!leadStages.some(([key])=>key===data.stage)||!['yes','no'].includes(data.promotion)||!['','female','male','other','unspecified'].includes(data.gender||'')||!['','hk','kowloon','nt'].includes(data.district||'')||(data.owner&&!previewTeachers.some(person=>person.name===data.owner)))error=t('請選擇有效的跟進階段及選項。','Choose a valid stage and options.');
 if(error){document.querySelector('#lead-editor-error').textContent=error;return}
 let now=new Date().toISOString();Object.assign(record,{id:current?.id||'L'+db.next++,stage:data.stage,promotion:data.promotion,gender:data.gender||'',district:data.district||'',owner:data.owner||'',active:current?.active!==false,createdAt:current?.createdAt||now,updatedAt:now,createdSource:'manual'});
 if(current)Object.assign(current,record);else db.leads.push(record);save();modal='';leadSearch='';leadStageFilter='';leadLevelFilter='';leadStatusFilter=record.active?'active':'archived';leadSelected.clear();render();toast(t('潛在客戶已儲存','Lead saved'));
}
function leadColumnsLists(){
 if(!leadColumnDraft)return '';let hidden=leadColumnDefinitions.map(([key])=>key).filter(key=>!leadColumnDraft.includes(key));
 return `<h3>${t('顯示中','Showing')}</h3><p class="lead-columns-instructions">${t('抓住三橫條拖動排序；也可選取手把後按上下方向鍵。','Drag the three-line handle to reorder, or focus the handle and use the arrow keys.')}</p><ul id="lead-shown-columns" class="lead-column-list">${leadColumnDraft.map(key=>`<li data-lead-column="${key}"><span>${leadColumnLabel(key)}</span><button type="button" class="lead-column-handle" data-lead-column-handle="${key}" aria-label="${t('拖動排序：','Drag to reorder: ')}${leadColumnLabel(key)}" aria-describedby="lead-column-status" aria-pressed="false"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" aria-hidden="true"><path d="M4 6h16M4 12h16M4 18h16"/></svg></button><button type="button" class="lead-column-visibility" data-action="lead-hide-column" data-column-key="${key}" ${key==='displayName'?'disabled':''} aria-label="${t('隱藏：','Hide: ')}${leadColumnLabel(key)}">−</button></li>`).join('')}</ul><h3 class="lead-hidden-heading">${t('隱藏','Hidden')}</h3><ul class="lead-column-list lead-hidden-columns">${hidden.map(key=>`<li><span>${leadColumnLabel(key)}</span><button type="button" class="lead-column-visibility" data-action="lead-show-column" data-column-key="${key}" aria-label="${t('顯示：','Show: ')}${leadColumnLabel(key)}">+</button></li>`).join('')}</ul><p id="lead-column-status" class="tt-sr-only" role="status"></p>`;
}
function openLeadColumns(){if(role!=='teacher')return;leadColumnDraft=shownLeadColumns();modal=`<div class="modal create-course-modal lead-columns-modal" role="dialog" aria-modal="true" aria-labelledby="lead-columns-title"><div class="dialog create-course-dialog lead-columns-dialog"><header class="create-course-header"><h2 id="lead-columns-title">${t('欄位','Columns')}</h2><button type="button" data-action="close" aria-label="${t('關閉','Close')}">×</button></header><div id="lead-columns-body" class="lead-columns-body">${leadColumnsLists()}</div><footer class="create-course-footer"><button type="button" data-action="lead-columns-save">OK</button></footer></div></div>`;renderModal();document.querySelector('.lead-column-handle').focus()}
function refreshLeadColumns(focusKey=''){document.querySelector('#lead-columns-body').innerHTML=leadColumnsLists();if(focusKey)document.querySelector(`[data-lead-column-handle="${focusKey}"]`)?.focus()}
function moveLeadColumnDraft(key,index){if(role!=='teacher'||!leadColumnDraft||!leadColumnDraft.includes(key)||!Number.isInteger(index))return false;let from=leadColumnDraft.indexOf(key),to=Math.max(0,Math.min(leadColumnDraft.length-1,index));if(from===to)return false;leadColumnDraft.splice(from,1);leadColumnDraft.splice(to,0,key);return true}
function announceLeadColumn(key){document.querySelector('#lead-column-status').textContent=t(`${leadColumnLabel(key)}：第 ${leadColumnDraft.indexOf(key)+1} 個欄位`,`${leadColumnLabel(key)}: column ${leadColumnDraft.indexOf(key)+1}`)}
function startLeadColumnDrag(e){let handle=e.target.closest?.('[data-lead-column-handle]');if(!handle||role!=='teacher'||!leadColumnDraft||e.isPrimary===false||(e.button!==undefined&&e.button!==0))return false;let key=handle.dataset.leadColumnHandle;if(!leadColumnDraft.includes(key))return false;e.preventDefault();leadColumnDrag={key,handle,pointerId:e.pointerId,x:e.clientX,y:e.clientY,before:[...leadColumnDraft],frame:null,capture:document.querySelector('#lead-columns-body')};leadColumnDrag.capture.setPointerCapture?.(e.pointerId);handle.setAttribute('aria-pressed','true');handle.closest('li').classList.add('is-dragging');return true}
function stepLeadColumnDrag(){let drag=leadColumnDrag;if(!drag||role!=='teacher'||!leadColumnDraft)return;let body=document.querySelector('#lead-columns-body'),list=document.querySelector('#lead-shown-columns'),bounds=body.getBoundingClientRect(),edge=42,speed=drag.y<bounds.top+edge?-12:drag.y>bounds.bottom-edge?12:0;body.scrollTop+=speed;let others=[...list.querySelectorAll('[data-lead-column]')].filter(row=>row.dataset.leadColumn!==drag.key),index=others.filter(row=>{let r=row.getBoundingClientRect();return drag.y>r.top+r.height/2}).length;if(moveLeadColumnDraft(drag.key,index)){let source=drag.handle.closest('li');list.insertBefore(source,others[index]||null);announceLeadColumn(drag.key)}if(speed&&leadColumnDrag&&window.requestAnimationFrame)drag.frame=window.requestAnimationFrame(()=>{drag.frame=null;stepLeadColumnDrag()})}
function moveLeadColumnDrag(e){if(!leadColumnDrag||e.pointerId!==leadColumnDrag.pointerId)return;leadColumnDrag.x=e.clientX;leadColumnDrag.y=e.clientY;e.preventDefault();if(!leadColumnDrag.frame)stepLeadColumnDrag()}
function finishLeadColumnDrag(cancel=false){let drag=leadColumnDrag;if(!drag)return;if(drag.frame)window.cancelAnimationFrame?.(drag.frame);leadColumnDrag=null;if(cancel)leadColumnDraft=drag.before;if(drag.capture.hasPointerCapture?.(drag.pointerId))drag.capture.releasePointerCapture(drag.pointerId);if(leadColumnDraft){refreshLeadColumns(drag.key);announceLeadColumn(drag.key)}}
function cancelLeadColumns(){finishLeadColumnDrag(true);leadColumnDraft=null}
function resetLeadUi(){cancelLeadColumns();leadSearch='';leadStageFilter='';leadLevelFilter='';leadStatusFilter='active';leadSelected.clear()}
function leadKeyboard(e){let handle=e.target?.closest?.('[data-lead-column-handle]');if(!handle||role!=='teacher'||!leadColumnDraft)return false;let key=handle.dataset.leadColumnHandle,from=leadColumnDraft.indexOf(key);if(!['ArrowUp','ArrowDown','Home','End'].includes(e.key)||from<0)return false;e.preventDefault();let index=e.key==='Home'?0:e.key==='End'?leadColumnDraft.length-1:from+(e.key==='ArrowUp'?-1:1);if(moveLeadColumnDraft(key,index)){refreshLeadColumns(key);announceLeadColumn(key)}return true}
function handleLeadAction(action,d){
 if(role!=='teacher')return;
 if(action==='lead-create'){openLeadEditor();return}if(action==='lead-edit'){openLeadEditor(d.leadId);return}if(action==='lead-columns'){openLeadColumns();return}
 if(action==='lead-clear-filters'){resetLeadUi();render();return}
 if(['lead-archive','lead-restore'].includes(action)){let rows=filteredLeads();for(let lead of rows.filter(lead=>leadSelected.has(lead.id))){lead.active=action==='lead-restore';lead.updatedAt=new Date().toISOString()}leadSelected.clear();save();render();return}
 if(!leadColumnDraft)return;
 if(action==='lead-columns-save'){finishLeadColumnDrag();db.leadColumns=normaliseLeadColumns(leadColumnDraft);leadColumnDraft=null;save();modal='';render();return}
 if(action==='lead-hide-column'&&d.columnKey!=='displayName'&&leadColumnDraft.includes(d.columnKey)){leadColumnDraft=leadColumnDraft.filter(key=>key!==d.columnKey);refreshLeadColumns();return}
 if(action==='lead-show-column'&&leadColumnDefinitions.some(([key])=>key===d.columnKey)&&!leadColumnDraft.includes(d.columnKey)){leadColumnDraft.push(d.columnKey);refreshLeadColumns(d.columnKey)}
}
document.addEventListener('change',e=>{
 if(role!=='teacher')return;let target=e.target;if(timetableSettingsDraft&&target.closest?.('#tt-view-settings')){updateTimetableSettingsDraft(target);return}
 if(['lead-status','lead-stage-filter','lead-level-filter'].includes(target.id)){if(target.id==='lead-status'&&['active','archived','all'].includes(target.value))leadStatusFilter=target.value;else if(target.id==='lead-stage-filter'&&(!target.value||leadStages.some(([key])=>key===target.value)))leadStageFilter=target.value;else if(target.id==='lead-level-filter')leadLevelFilter=target.value;leadSelected.clear();render();return}
 if(target.id==='lead-select-all'){for(let lead of filteredLeads())if(target.checked)leadSelected.add(lead.id);else leadSelected.delete(lead.id)}else if(target.name==='lead-selection'&&db.leads.some(lead=>lead.id===target.value)){if(target.checked)leadSelected.add(target.value);else leadSelected.delete(target.value)}else return;
 let rows=filteredLeads(),all=document.querySelector('#lead-select-all');all.checked=!!rows.length&&rows.every(lead=>leadSelected.has(lead.id));all.indeterminate=rows.some(lead=>leadSelected.has(lead.id))&&!all.checked;document.querySelector('#lead-selection-actions').innerHTML=leadSelectionActions();
});

