function renderModal(){document.querySelector('#modal-root').innerHTML=modal}
function render(){let p=path();if(p.startsWith('/account')&&!role){go('/login');return}if((p.startsWith('/account/classes/')||p.startsWith('/account/courses/'))&&role!=='teacher'){go('/account');return}document.documentElement.lang=lang==='zh'?'zh-Hant':'en';let body=p==='/'?home():p==='/about'?about():p==='/portfolio'?portfolio():p==='/classes'?`<h1 class="title">${t('課程','Courses')}</h1><p class="sub">${'Sample'}</p>${cards()}`:p.startsWith('/classes/')?detail(p.split('/')[2]):p==='/faq'?`<h1 class="title">FAQ</h1>${faq()}`:p==='/privacy'?privacy():p==='/login'?login():p==='/join'?joinForm():p==='/confirmation'?confirmation():p==='/payment'?paymentPage():p==='/payment-success'?paymentSuccess():p==='/account'||p.startsWith('/account/classes/')||p.startsWith('/account/courses/')?account():p==='/schedule'?schedule():p==='/news'?newsPage():p==='/join-us'?`<h1 class="title">${t('加入我們','Join Us')}</h1><div class="panel">Sample</div>`:missing();document.querySelector('#app').innerHTML=header()+`<main class="${isAccountPage()?'portal-main':'wrap'}">${body}</main>${isAccountPage()?'':footer()}<div id="modal-root">${modal}</div>`;syncPortfolioRotation(p);syncPortalMenu()}
function joinDetailsError(data){let student=String(data.student??'').trim(),phone=String(data.phone??'').trim(),email=String(data.email??'').trim();if(!student||!email||!phone)return t('請填寫姓名、電話及電郵。','Please enter a name, phone number and email.');if(!/^[\p{L}\p{M} ]+$/u.test(student))return t('學生姓名只可包含文字及空格。','Student name may contain letters and spaces only.');if(!/^[0-9]+$/.test(phone))return t('電話只可包含數字。','Phone number may contain digits only.');return ''}
function markPaid(b){if(!b||b.status==='waitlist')return false;if(!b.paid){let paidAt=new Date().toISOString();let count=b.lessonCount||termLessons(cl(b.classId));if(lessonDatesForClass(cl(b.classId),paidAt,count).length!==count)return false;b.lessonCount=count;b.paid=true;b.paidAt=paidAt}b.status='confirmed';save();return true}
