document.addEventListener('pointermove',e=>{if(leadColumnDrag){moveLeadColumnDrag(e);return}if(!classCropDrag||!classCrop)return;let drag=classCropDrag,dx=(e.clientX-drag.startX)/drag.rect.width,dy=(e.clientY-drag.startY)/drag.rect.height;if(drag.resize){let maxWidth=Math.min(.98,.98*classPhotoRatio/classCrop.aspect,1-drag.x,(1-drag.y)*classPhotoRatio/classCrop.aspect),minWidth=Math.min(.15,maxWidth/2);classCrop.width=clampCrop(drag.width+(dx+dy*classPhotoRatio/classCrop.aspect)/2,minWidth,maxWidth);document.querySelector('#class-crop-size').value=Math.round(classCrop.width/Math.min(.98,.98*classPhotoRatio/classCrop.aspect)*100)}else{classCrop.x=clampCrop(drag.x+dx,0,1-classCrop.width);classCrop.y=clampCrop(drag.y+dy,0,1-cropHeight(classCrop))}updateClassCropFrame()});
document.addEventListener('pointerup',e=>{if(leadColumnDrag&&e.pointerId===leadColumnDrag.pointerId)finishLeadColumnDrag();classCropDrag=null});
document.addEventListener('pointercancel',e=>{if(leadColumnDrag&&e.pointerId===leadColumnDrag.pointerId)finishLeadColumnDrag(true);classCropDrag=null});
document.addEventListener('change',e=>{if(e.target.id==='income-month'&&/^\d{4}-\d{2}$/.test(e.target.value)){incomeMonth=e.target.value;let [y,m]=incomeMonth.split('-').map(Number);incomeEnd=new Date(y,m-1,1);render()}});
document.addEventListener('change',e=>{
 if(role!=='teacher')return;let target=e.target;if(scheduleEndDraft&&['endWeekday','endMode','endDate','count','mustAttendAll'].includes(target.name)){updateScheduleEndDraft(target);return}if(target.name==='scheduleWeekday'&&scheduleDraft){let selected=new Set(scheduleDraft.weekdays);if(target.checked)selected.add(Number(target.value));else selected.delete(Number(target.value));scheduleDraft.weekdays=[...selected];scheduleDraft.customWeekdays=true;syncScheduleFields();return}
 if(target.id==='tt-list-all'){document.querySelectorAll('.tt-list-select').forEach(input=>input.checked=target.checked);return}if(target.classList?.contains('tt-list-select')){let inputs=[...document.querySelectorAll('.tt-list-select')],all=document.querySelector('#tt-list-all');all.checked=inputs.every(input=>input.checked);all.indeterminate=inputs.some(input=>input.checked)&&!all.checked;return}if(target.id==='tt-date'){if(!validISODate(target.value))return;selectTimetableDate(target.value)}
 else if(target.id==='tt-view'){if(!['day','week','month','list'].includes(target.value))return;timetableView=target.value}
 else if(target.id==='tt-hide-empty')timetableHideEmpty=target.checked;
 else if(target.id==='tt-all-resources')timetableSelections[timetableResource]=target.checked?timetableResourceOptions().map(o=>o.id):[];
 else if(target.name==='tt-resource'){if(!timetableResourceOptions().some(o=>o.id===target.value))return;let selected=new Set(timetableSelections[timetableResource]);if(target.checked)selected.add(target.value);else selected.delete(target.value);timetableSelections[timetableResource]=[...selected]}
 else return;render();
});
document.addEventListener('keydown',e=>{if(scheduleEndDraft&&modal){if(e.key==='Escape'){e.preventDefault();closeScheduleEnd();return}if(e.key==='Tab'){let controls=[...document.querySelectorAll('.schedule-end-dialog button:not(:disabled),.schedule-end-dialog input:not(:disabled)')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}return}if(timetableSettingsDraft&&modal){if(e.key==='Escape'){e.preventDefault();closeTimetableViewSettings();return}if(e.key==='Tab'){let controls=[...document.querySelectorAll('.tt-settings-dialog button:not(:disabled),.tt-settings-dialog input:not(:disabled),.tt-settings-dialog select:not(:disabled)')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}if(e.key==='Escape'){let attendance=document.querySelector('#tt-attendance');if(attendance?.open){e.preventDefault();attendance.open=false;attendance.querySelector('summary')?.focus();return}}if(e.key==='Escape'&&leadColumnDrag){e.preventDefault();finishLeadColumnDrag(true);return}if(leadKeyboard(e))return;if(e.key==='Tab'&&modal&&(modal.includes('lead-columns-dialog')||modal.includes('lead-editor-dialog'))){let controls=[...document.querySelectorAll('.lead-columns-dialog button:not(:disabled),.lead-editor-dialog button:not(:disabled),.lead-editor-dialog input:not(:disabled),.lead-editor-dialog select:not(:disabled),.lead-editor-dialog textarea:not(:disabled)')],first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();return}if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();return}}if(selectedTimetableLesson&&e.key==='Escape'&&lessonMenuOpen){e.preventDefault();setLessonMenu(false,true);return}if(selectedTimetableLesson&&['ArrowDown','ArrowUp','Home','End'].includes(e.key)&&e.target?.closest('.lesson-more')){e.preventDefault();if(!lessonMenuOpen){setLessonMenu(true,true);return}let items=[...document.querySelectorAll('#lesson-more-menu button')],index=items.indexOf(document.activeElement),next=e.key==='Home'?0:e.key==='End'?items.length-1:(index+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items[next]?.focus();return}if(e.key==='Escape'&&modal){if(selectedTimetableLesson)closeTimetableLesson();else{cancelLeadColumns();scheduleDraft=null;scheduleEndDraft=null;schedulePreviewVisible=false;modal='';renderModal()}}if(e.key==='Tab'&&selectedTimetableLesson&&modal){let controls=[...document.querySelectorAll('.lesson-dialog button:not(:disabled)')].filter(button=>!button.closest('[hidden]')),first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});window.addEventListener('popstate',render);portalViewport?.addEventListener('change',syncPortalMenu);save();render();

document.addEventListener('change',e=>{if(role!=='teacher'||!accountCourseId())return;if(e.target.id==='course-detail-month'&&/^\d{4}-\d{2}$/.test(e.target.value)&&validISODate(e.target.value+'-01')){courseDetailMonth=timetableDateObject(e.target.value+'-01');courseDetailMonth.setDate(1);render()}if(e.target.id==='course-detail-view'&&e.target.value==='timetable'){tab='overview';timetableLessonFilter=null;selectTimetableDate(timetableDate.slice(0,7)===timetableDateKey(courseDetailMonth).slice(0,7)?timetableDate:courseScheduleGroups(accountCourseId())[0]?.dates[0]||timetableDateKey(courseDetailMonth));timetableSearch=db.classes.find(c=>c.course===accountCourseId())?.courseName||courses.find(c=>c.id===accountCourseId())?.e||accountCourseId();go('/account')}});
